<script setup lang="ts">
import {ref,onMounted} from 'vue';import {get} from '../../../../packages/shared/src/client';import {useTask,type Row} from '../../../../packages/shared/src/ui';import Status from '../../../../packages/shared/src/Status.vue';
const task=useTask(),module=ref('user'),actor=ref(''),result=ref(''),requestId=ref(''),page=ref(1),total=ref(0),rows=ref<Row[]>([]),modules=['auth','user','course','learning','exam','trade','pay','promotion','media','search','message','remark'];
async function load(){await task.run(async()=>{const params=new URLSearchParams({pageNo:String(page.value),pageSize:'20'});if(actor.value)params.set('actor',actor.value);if(result.value)params.set('result',result.value);if(requestId.value)params.set('requestId',requestId.value);const data=await get<Row>('/admin/audit/'+module.value+'?'+params);rows.value=data.list;total.value=Number(data.total);});}
onMounted(load);
</script><template><section class="card"><h2>管理操作审计</h2><Status :busy="task.busy.value" :error="task.error.value"/><p class="muted">受理中的异步操作显示 ACCEPTED；最终状态通过同一请求编号在操作记录中核对。</p><el-select v-model="module" aria-label="选择审计模块" :disabled="task.busy.value"><el-option v-for="item in modules" :key="item" :value="item" :label="item"/></el-select><el-input v-model="actor" aria-label="操作者编号" placeholder="操作者编号"/><el-select v-model="result" aria-label="处理结果" clearable placeholder="处理结果"><el-option v-for="item in ['IN_PROGRESS','FAILED','ACCEPTED','SUCCEEDED']" :key="item" :value="item" :label="item"/></el-select><el-input v-model="requestId" aria-label="请求编号" placeholder="请求编号"/><el-button @click="page=1;load()" :disabled="task.busy.value">查询</el-button><el-table :data="rows"><el-table-column prop="actor_id" label="操作者"/><el-table-column prop="object_path" label="操作对象"/><el-table-column prop="result" label="结果"/><el-table-column prop="request_id" label="请求编号"/><el-table-column prop="created_at" label="发生时间"/></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next, total" @current-change="load"/></section></template>
